//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::int::div_exact, int::mul, int::emod`; the
//! native twin is `benches/native/Bench/IntDivExact.lean`.
//! Int words in the int32 range on both sides; every result stays there; both sides make the
//! program's test that supplies the proof (`b ∣ a`, a remainder)

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::int;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(acc, {
            let b = int_box((((x >> 4) & 0xFF) as i64) - 128);
            let a = int_res(int::mul(
                int_arg(int_box(((x >> 48) as i64) - (1 << 15))),
                int_arg(b),
            ));
            if int::emod(int_arg(a), int_arg(b)).is_zero() {
                int_unbox(int_res(int::div_exact(int_arg(a), int_arg(b)))) as u64
            } else {
                0
            }
        });
    }
    acc
}

fn main() {
    run(|| (), kernel)
}
